:root {
  --bg: #f2efe8;
  --paper: rgba(255, 252, 247, 0.92);
  --ink: #182126;
  --muted: #51606b;
  --accent: #0f766e;
  --accent-strong: #115e59;
  --line: rgba(24, 33, 38, 0.12);
  --shadow: 0 24px 60px rgba(24, 33, 38, 0.08);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: Georgia, 'Times New Roman', serif;
  color: var(--ink);
  background:
    radial-gradient(circle at top left, rgba(15, 118, 110, 0.14), transparent 30%),
    linear-gradient(180deg, #fbf7f0 0%, var(--bg) 100%);
}
a { color: inherit; text-decoration: none; }
.site-shell { width: min(1120px, calc(100% - 32px)); margin: 0 auto; padding: 24px 0 48px; }
.site-header, .site-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.site-header {
  position: sticky;
  top: 12px;
  z-index: 10;
  margin-bottom: 24px;
  padding: 16px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 252, 247, 0.85);
  backdrop-filter: blur(12px);
}
.brand { font-size: 1.15rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; }
.site-nav { display: flex; flex-wrap: wrap; gap: 18px; color: var(--muted); }
.hero, .workflow-panel, .page-intro, .contact-card {
  border: 1px solid var(--line);
  border-radius: 28px;
  background: var(--paper);
  box-shadow: var(--shadow);
}
.hero { padding: 72px 56px; }
.eyebrow { margin: 0 0 12px; color: var(--accent-strong); text-transform: uppercase; letter-spacing: 0.14em; font-size: 0.8rem; }
h1, h2 { line-height: 1.05; margin: 0 0 16px; }
h1 { font-size: clamp(2.8rem, 8vw, 5.6rem); max-width: 11ch; }
h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); }
.lede { max-width: 60ch; font-size: 1.1rem; color: var(--muted); }
.hero-actions, .footer-links { display: flex; flex-wrap: wrap; gap: 12px; }
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid var(--line);
}
.button.primary { background: var(--accent); color: #f8fffd; border-color: var(--accent); }
.button.secondary { background: transparent; }
.proof-strip, .content-grid { display: grid; gap: 18px; margin-top: 24px; }
.proof-strip { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.content-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.content-grid.two-up { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.proof-strip > div, .card {
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.65);
}
.proof-strip strong, .workflow-list li::marker { color: var(--accent-strong); }
.proof-strip span, .card p, .workflow-list { color: var(--muted); }
.workflow-panel, .page-intro, .contact-card { padding: 36px; margin-top: 24px; }
.workflow-list { margin: 0; padding-left: 20px; display: grid; gap: 10px; }
.site-footer { margin-top: 28px; padding: 8px 4px 0; color: var(--muted); }
@media (max-width: 820px) {
  .hero { padding: 40px 24px; }
  .proof-strip, .content-grid, .content-grid.two-up { grid-template-columns: 1fr; }
  .site-header, .site-footer { flex-direction: column; align-items: flex-start; }
}

